&gt;&gt; Hi Mark,<br>&gt;&gt; <br>&gt;&gt; Could you send me the graph as an RData object?<br>&gt;&gt; There are some &#39;pathological&#39; cases I am coming to recognize.<br>&gt;&gt; <br>&gt;&gt; Of course, they should not be pathological.  They are only that way because of my sometimes dumb way of doing things.<br>&gt;&gt; <br>&gt;&gt; Send me the graph, I&#39;ll send you a fix.  (I promise boldly!)<br>&gt;&gt; <br>&gt;&gt; - Paul<br>&gt;&gt; <br>&gt;&gt; On May 7, 2012, at 4:03 PM, Grimes Mark wrote:<br>&gt;&gt; <br>&gt;&gt;&gt; Paul<br>&gt;&gt;&gt; <br>&gt;&gt;&gt; The Cytoscape.Window or new.Cytoscape.Window command takes a VERY long time to execute when the number of Nodes is 2482 and number of attributes is 234.  The makeSimpleGraph command just took a few seconds in Cytoscape v 2.8.3.   At first I thought it was hung, but the cpu is occupied by R.<br>&gt;&gt;&gt; <br>&gt;&gt;&gt; By the way I wrote functions to load attributes into a graph and edges into a cytoscape window that are reproduced below.  In case anyone may find them useful.<br>&gt;&gt;&gt; <br>&gt;&gt;&gt; Mark<br>&gt;&gt;&gt; <br>&gt;&gt;&gt; #  Function to plot the primary cytoscape file<br>&gt;&gt;&gt; # 	syntax: &gt; mywindowname &lt;- <a href="http://plot.cy" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://plot.cy&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw3AMyQ4FhBFnogMuqRaxSeq">plot.cy</a>(cytoscape.file)<br>&gt;&gt;&gt; #<br>&gt;&gt;&gt; <a href="http://plot.cy" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://plot.cy&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw3AMyQ4FhBFnogMuqRaxSeq">plot.cy</a> &lt;-function (cytoscape.file) {<br>&gt;&gt;&gt; 		mydata &lt;- new(&quot;graphNEL&quot;, edgemode=&#39;undirected&#39;, nodes=as.character(cytoscape.file[, 1]))<br>&gt;&gt;&gt; #	Set up and load all the node attributes<br>&gt;&gt;&gt; 	for (i in 2:ncol(cytoscape.file)) {<br>&gt;&gt;&gt; 		mydata &lt;- initNodeAttribute (graph=mydata,  <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a>=names(cytoscape.file[i]), attribute.type=&#39;numeric&#39;, default.value=0.0)<br>&gt;&gt;&gt; 		nodeData (mydata, n=as.character(cytoscape.file[, 1]), attr=names(cytoscape.file[i])) &lt;- as.numeric(cytoscape.file[,i])<br>&gt;&gt;&gt; 				}<br>&gt;&gt;&gt; 		# load standard edge attributes<br>&gt;&gt;&gt; 		mydata &lt;- initEdgeAttribute (graph= mydata, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;, default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt; 		mydata &lt;- initEdgeAttribute(mydata, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a> = &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt; 		return(mydata)	}<br>&gt;&gt;&gt; #<br>&gt;&gt;&gt; #  Function to load a single edge:<br>&gt;&gt;&gt; 	load.an.edge &lt;- function (Cy_Wind, Network.File) {<br>&gt;&gt;&gt; 			filename=NULL<br>&gt;&gt;&gt; 			 a = as.character(Network.File$Gene.1)<br>&gt;&gt;&gt; 			 b = as.character(Network.File $Gene.2)<br>&gt;&gt;&gt; 			nodenames &lt;- unique(c(a,b))			<br>&gt;&gt;&gt; 			edgeTypes &lt;- levels(as.factor(Network.File$edgeType))<br>&gt;&gt;&gt; 			subgraph2 &lt;- new(&quot;graphNEL&quot;, nodes= nodenames, edgemode=&#39;undirected&#39;)<br>&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute (graph= subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;, default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute(subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a> = &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt; 			subgraph2 = addEdge (as.vector(Network.File$Gene.1, mode=&quot;character&quot;), as.vector(Network.File$Gene.2, mode=&quot;character&quot;), subgraph2)<br>&gt;&gt;&gt; 			edgeData (subgraph2, as.vector(Network.File$Gene.1, mode=&quot;character&quot;), as.vector(Network.File$Gene.2, mode=&quot;character&quot;), attr=&#39;edgeType&#39;) &lt;- as.character(Network.File$edgeType)<br>&gt;&gt;&gt; 			edgeData (subgraph2, as.vector(Network.File$Gene.1, mode=&quot;character&quot;), as.vector(Network.File$Gene.2, mode=&quot;character&quot;), attr=&#39;Weight&#39;) &lt;- Network.File$Weight<br>&gt;&gt;&gt; 			addGraphToGraph (Cy_Wind, subgraph2)	<br>&gt;&gt;&gt; 			redraw(Cy_Wind) 	<br>&gt;&gt;&gt; 			showGraphicsDetails(Cy_Wind, TRUE)<br>&gt;&gt;&gt; 			}<br>&gt;&gt;&gt; 			###<br>&gt;&gt;&gt; #<br>&gt;&gt;&gt; # Function to load multiple edges:<br>&gt;&gt;&gt; 	loadedges &lt;- function (Cy_Wind, Network.File) {<br>&gt;&gt;&gt; 			filename=NULL<br>&gt;&gt;&gt; 			 a = as.character(Network.File$Gene.1)<br>&gt;&gt;&gt; 			 b = as.character(Network.File $Gene.2)<br>&gt;&gt;&gt; 			nodenames &lt;- unique(c(a,b))			<br>&gt;&gt;&gt; 			edgeTypes &lt;- levels(as.factor(Network.File$edgeType))<br>&gt;&gt;&gt; 			sepedges &lt;- dlply(Network.File, .(edgeType))<br>&gt;&gt;&gt; 			subgraph2 &lt;- new(&quot;graphNEL&quot;, nodes= nodenames, edgemode=&#39;undirected&#39;)<br>&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute (graph= subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;, default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute(subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590817000&amp;usg=AOvVaw0W9KrIRK1N--4kvSzJjFSR">attribute.name</a> = &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt; 			#<br>&gt;&gt;&gt; 			for(i in 1:length(sepedges))	{<br>&gt;&gt;&gt; 				filename[i] &lt;- paste(edgeTypes[i], noquote(&quot;edges&quot;), sep=&quot; &quot;, collapse=NULL)<br>&gt;&gt;&gt; 				edgefile &lt;- data.frame(sepedges[i])<br>&gt;&gt;&gt; 				names(edgefile) &lt;- names(Network.File)<br>&gt;&gt;&gt; 				subgraph2 = addEdge (as.vector(edgefile$Gene.1, mode=&quot;character&quot;), as.vector(edgefile$Gene.2, mode=&quot;character&quot;), subgraph2)<br>&gt;&gt;&gt; 				edgeData (subgraph2, as.vector(edgefile$Gene.1, mode=&quot;character&quot;), as.vector(edgefile$Gene.2, mode=&quot;character&quot;), attr=&#39;edgeType&#39;) &lt;- as.character(edgefile$edgeType)<br>&gt;&gt;&gt; 				edgeData (subgraph2, as.vector(edgefile$Gene.1, mode=&quot;character&quot;), as.vector(edgefile$Gene.2, mode=&quot;character&quot;), attr=&#39;Weight&#39;) &lt;-edgefile$Weight<br>&gt;&gt;&gt; 				addGraphToGraph (Cy_Wind, subgraph2)	<br>&gt;&gt;&gt; 				redraw(Cy_Wind) 	<br>&gt;&gt;&gt; 				cat(&quot;
&quot;, filename[i], &quot;
&quot;)<br>&gt;&gt;&gt; 					}<br>&gt;&gt;&gt; 				cat(&quot;
&quot;, filename) 	<br>&gt;&gt;&gt; 				showGraphicsDetails(Cy_Wind, TRUE)<br>&gt;&gt;&gt; 				}<br>&gt;&gt;&gt; 				#<br>&gt;&gt;&gt; <br>&gt;&gt;&gt; <br>&gt;&gt; <br>&gt; <br><br>

&gt; Yes, you can do that straightforwardly.  I can send you a working- <br>&gt; code example later today, but here&#39;s some pseudo-code<br>&gt;<br>&gt; cw = demoSimpleGraph ()<br>&gt;<br>&gt; selectNodes (cw, c (&#39;A&#39;, &#39;B&#39;))<br>&gt;<br>&gt; cw2 = createWindowFromSelection (cw, &#39;demo2&#39;, return.graph=TRUE)<br>&gt; g2 = getGraph (cw2)<br>&gt;<br>&gt; setNodeAttributeDirect (cw2,<br>&gt;<br>&gt; stopifnot (&#39;count&#39; %in% noa.names (g2)<br>&gt; result = setNodeAttributesDirect (cw2, &#39;count&#39;, &#39;int&#39;, c (&#39;A&#39;, &#39;B&#39;),  <br>&gt; c (4, 8))<br>&gt;<br>&gt; If, on the other hand, you want to add an entirely new node  <br>&gt; attribute to g2, you will have a few extra steps.<br>&gt;<br>&gt; Let me know…<br>&gt;<br>&gt; - Paul<br>&gt;<br>&gt;<br>&gt; On May 9, 2012, at 5:24 AM, Mark Grimes wrote:<br>&gt;<br>&gt;&gt; Paul<br>&gt;&gt;<br>&gt;&gt; Thanks very much for fixing those things.<br>&gt;&gt;<br>&gt;&gt; I am still not understanding something though.  Is it possible to  <br>&gt;&gt; access the graph in the slot in the window object?  The goal is to  <br>&gt;&gt; send a new attribute to the subgraph that wasn&#39;t in the original  <br>&gt;&gt; (to plot with node size for example).<br>&gt;&gt;<br>&gt;&gt; Mark<br>&gt;&gt;<br>&gt;&gt;<br>&gt;&gt; On May 8, 2012, at 9:23 PM, Paul Shannon wrote:<br>&gt;&gt;<br>&gt;&gt;&gt; Hi Mark,<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; Thanks for these reports, and these questions.  I updated the rcy  <br>&gt;&gt;&gt; website so that setNodePosition is now documented.  I have since  <br>&gt;&gt;&gt; learned that, rather than simply removing a method, I should  <br>&gt;&gt;&gt; &#39;deprecate&#39; for a release cycle, and only then remove it.  Sorry  <br>&gt;&gt;&gt; you got stung.<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; In the website&#39;s man page for createNewWindowFromSelection<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; <a href="http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/methods/createWindowFromSelection.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/methods/createWindowFromSelection.html&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw0fmnsOaiEJFecXU-na-WYq">http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/methods/createWindowFromSelection.html</a><br>&gt;&gt;&gt;<br>&gt;&gt;&gt; under &#39;Value&#39; -- meaning &quot;the value which the method returns&quot; is  <br>&gt;&gt;&gt; this line:<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; A new CytoscapeWindow object, with the graph slot populated with  <br>&gt;&gt;&gt; the new<br>&gt;&gt;&gt; selected subgraph, if requested. If not requested, the graph slot  <br>&gt;&gt;&gt; holds an empty graph.<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; Does that make more sense?<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; - Paul<br>&gt;&gt;&gt;<br>&gt;&gt;&gt;<br>&gt;&gt;&gt; On May 8, 2012, at 2:05 PM, Grimes Mark wrote:<br>&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt; PS an update on the error<br>&gt;&gt;&gt;&gt;&gt; But now it didn&#39;t work with my list of gene names, which is how  <br>&gt;&gt;&gt;&gt;&gt; I sent the graph to Cy.  Maybe because the node name in Cy is  <br>&gt;&gt;&gt;&gt;&gt; now (conveniently) &#39;ValidatedObjectAndEditString:  <br>&gt;&gt;&gt;&gt;&gt; validatedObject=TNK2, editString=NULL&#39; when copied and pasted?    <br>&gt;&gt;&gt;&gt;&gt; &quot;ERROR! unknown nodes in RCytoscape::setNodePosition&quot;<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt; This error only occurred on a second window that I created using  <br>&gt;&gt;&gt;&gt; createWindowFromSelection().  Function setNodePosition() worked  <br>&gt;&gt;&gt;&gt; fine on the original window created with RCy.  Not sure why,  <br>&gt;&gt;&gt;&gt; perhaps because I set return.graph=FALSE?<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt; By the way, is there a way to modify attributes from  <br>&gt;&gt;&gt;&gt; createWindowFromSelection()?  If you set return.graph =  TRUE?  I  <br>&gt;&gt;&gt;&gt; don&#39;t know how to access the graph object within the returned  <br>&gt;&gt;&gt;&gt; window object.<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt; Mark<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt; On May 8, 2012, at 1:45 PM, Paul Shannon wrote:<br>&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt; It is now setNodePosition.   There were too many name collisions  <br>&gt;&gt;&gt;&gt;&gt; with &#39;setPosition&#39;<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt; See <a href="http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/news.html" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/news.html&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw0Xeh3NWRzoXqslS4Nl9ksb">http://db.systemsbiology.net:8080/cytoscape/RCytoscape/versions/current/news.html</a> <br>&gt;&gt;&gt;&gt;&gt;   for other small changes.<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt; Sorry for the trouble.  I should have done a better job of  <br>&gt;&gt;&gt;&gt;&gt; getting the word out.<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt; - Paul<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt; On May 8, 2012, at 8:49 AM, Grimes Mark wrote:<br>&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; Paul<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; The graph is displayed when fewer attributes are included.<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; But. A new problem:<br>&gt;&gt;&gt;&gt;&gt;&gt; \<br>&gt;&gt;&gt;&gt;&gt;&gt; setPosition(lung.window, as.character(cyf$Gene.Name), sed.ord2)<br>&gt;&gt;&gt;&gt;&gt;&gt; Error: could not find function &quot;setPosition&quot;<br>&gt;&gt;&gt;&gt;&gt;&gt; RCytoscape::setPosition(lung.window, as.character(cyf <br>&gt;&gt;&gt;&gt;&gt;&gt; $Gene.Name), sed.ord2)<br>&gt;&gt;&gt;&gt;&gt;&gt; Error: &#39;setPosition&#39; is not an exported object from  <br>&gt;&gt;&gt;&gt;&gt;&gt; &#39;namespace:Rycytoscape&#39;<br>&gt;&gt;&gt;&gt;&gt;&gt; /<br>&gt;&gt;&gt;&gt;&gt;&gt; Something broke - this used to work.<br>&gt;&gt;&gt;&gt;&gt;&gt; SessionInfo:<br>&gt;&gt;&gt;&gt;&gt;&gt; Cytoscape 2.8.3; RCytoscape_1.6.3<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; Thanks for your help,<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; Mark<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt; On May 7, 2012, at 5:57 PM, Paul Shannon wrote:<br>&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; Hi Mark,<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; Could you send me the graph as an RData object?<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; There are some &#39;pathological&#39; cases I am coming to recognize.<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; Of course, they should not be pathological.  They are only  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; that way because of my sometimes dumb way of doing things.<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; Send me the graph, I&#39;ll send you a fix.  (I promise boldly!)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; - Paul<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt; On May 7, 2012, at 4:03 PM, Grimes Mark wrote:<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; Paul<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; The Cytoscape.Window or new.Cytoscape.Window command takes a  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; VERY long time to execute when the number of Nodes is 2482  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; and number of attributes is 234.  The makeSimpleGraph command  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; just took a few seconds in Cytoscape v 2.8.3.   At first I  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; thought it was hung, but the cpu is occupied by R.<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; By the way I wrote functions to load attributes into a graph  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; and edges into a cytoscape window that are reproduced below.   <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; In case anyone may find them useful.<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; Mark<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt;<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #  Function to plot the primary cytoscape file<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; # 	syntax: &gt; mywindowname &lt;- <a href="http://plot.cy" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://plot.cy&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw0BpPTECoBNzby5bjCcTMQk">plot.cy</a>(cytoscape.file)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; <a href="http://plot.cy" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://plot.cy&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw0BpPTECoBNzby5bjCcTMQk">plot.cy</a> &lt;-function (cytoscape.file) {<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		mydata &lt;- new(&quot;graphNEL&quot;, edgemode=&#39;undirected&#39;,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; nodes=as.character(cytoscape.file[, 1]))<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #	Set up and load all the node attributes<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 	for (i in 2:ncol(cytoscape.file)) {<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		mydata &lt;- initNodeAttribute (graph=mydata,   <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a>=names(cytoscape.file[i]),  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; attribute.type=&#39;numeric&#39;, default.value=0.0)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		nodeData (mydata, n=as.character(cytoscape.file[, 1]),  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; attr=names(cytoscape.file[i])) &lt;-  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; as.numeric(cytoscape.file[,i])<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				}<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		# load standard edge attributes<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		mydata &lt;- initEdgeAttribute (graph= mydata,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		mydata &lt;- initEdgeAttribute(mydata, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a> =  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 		return(mydata)	}<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #  Function to load a single edge:<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 	load.an.edge &lt;- function (Cy_Wind, Network.File) {<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			filename=NULL<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			 a = as.character(Network.File$Gene.1)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			 b = as.character(Network.File $Gene.2)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			nodenames &lt;- unique(c(a,b))			<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			edgeTypes &lt;- levels(as.factor(Network.File$edgeType))<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- new(&quot;graphNEL&quot;, nodes= nodenames,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; edgemode=&#39;undirected&#39;)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute (graph= subgraph2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute(subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a> =  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 = addEdge (as.vector(Network.File$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(Network.File$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), subgraph2)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			edgeData (subgraph2, as.vector(Network.File$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(Network.File$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), attr=&#39;edgeType&#39;) &lt;-  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; as.character(Network.File$edgeType)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			edgeData (subgraph2, as.vector(Network.File$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(Network.File$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), attr=&#39;Weight&#39;) &lt;- Network.File$Weight<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			addGraphToGraph (Cy_Wind, subgraph2)	<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			redraw(Cy_Wind) 	<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			showGraphicsDetails(Cy_Wind, TRUE)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			}<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			###<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; #<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; # Function to load multiple edges:<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 	loadedges &lt;- function (Cy_Wind, Network.File) {<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			filename=NULL<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			 a = as.character(Network.File$Gene.1)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			 b = as.character(Network.File $Gene.2)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			nodenames &lt;- unique(c(a,b))			<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			edgeTypes &lt;- levels(as.factor(Network.File$edgeType))<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			sepedges &lt;- dlply(Network.File, .(edgeType))<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- new(&quot;graphNEL&quot;, nodes= nodenames,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; edgemode=&#39;undirected&#39;)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute (graph= subgraph2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a>=&#39;edgeType&#39;, attribute.type=&#39;char&#39;,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; default.value=&#39;undefined&#39;)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			subgraph2 &lt;- initEdgeAttribute(subgraph2, <a href="http://attribute.name" target="_blank" rel="nofollow" data-saferedirecturl="https://www.google.com/url?hl=en-US&amp;q=http://attribute.name&amp;source=gmail&amp;ust=1793244590861000&amp;usg=AOvVaw1zgVhGazNqDTeSe43LEjK_">attribute.name</a> =  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; &quot;Weight&quot;, attribute.type = &quot;numeric&quot;, default.value = 0.0)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			#<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 			for(i in 1:length(sepedges))	{<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				filename[i] &lt;- paste(edgeTypes[i], noquote(&quot;edges&quot;),  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; sep=&quot; &quot;, collapse=NULL)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				edgefile &lt;- data.frame(sepedges[i])<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				names(edgefile) &lt;- names(Network.File)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				subgraph2 = addEdge (as.vector(edgefile$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(edgefile$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), subgraph2)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				edgeData (subgraph2, as.vector(edgefile$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(edgefile$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), attr=&#39;edgeType&#39;) &lt;- as.character(edgefile <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; $edgeType)<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				edgeData (subgraph2, as.vector(edgefile$Gene.1,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), as.vector(edgefile$Gene.2,  <br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; mode=&quot;character&quot;), attr=&#39;Weight&#39;) &lt;-edgefile$Weight<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				addGraphToGraph (Cy_Wind, subgraph2)	<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				redraw(Cy_Wind) 	<br>&gt;&gt;&gt;&gt;&gt;&gt;&gt;&gt; 				cat(&quot;
